                <span className="text-[#D4AF37] font-bold">[SYSTEM INIT]:</span>
                <p className="text-[#E5E7EB]/80 text-xs mt-1">{contentMap['Memory'].body[0]}</p>
              </div>
            </div>
          )}

          {activeView === 'Docs' && (
            <div className={outerContainerClass}>
              <h2 className={headerClass}>Architecture Documentation Repository</h2>
              <div className={glassCardClass}>
                <h3 className="text-sm font-bold text-white">01_rules_of_engagement.md</h3>
                <p className={secondaryText}>{contentMap['Docs'].body[0]}</p>
              </div>
            </div>
          )}

          {activeView === 'Team' && (
            <div className={outerContainerClass}>
              <h2 className={headerClass}>Director-Level Systems Organization</h2>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className={glassCardClass}><h3 className="text-sm font-bold text-white">Charlie</h3><p className={secondaryText}>Coding Lead (MQL4/MQL5 scripting).</p></div>
                <div className={glassCardClass}><h3 className="text-sm font-bold text-white">Tess</h3><p className={secondaryText}>Quant Analyst (Volatility scanning).</p></div>
                <div className={glassCardClass}><h3 className="text-sm font-bold text-white">Roxy</h3><p className={secondaryText}>UI/UX Director (Brand specs).</p></div>
                <div className={glassCardClass}><h3 className="text-sm font-bold text-white">Jack</h3><p className={secondaryText}>Backend Infrastructure (Server connections).</p></div>
              </div>
            </div>
          )}

        </div>
      </div>
    </div>
  );
}
